require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../core/CeoDashboardExcel.php';require_once __DIR__.'/../lib/ManagementReportsRepository.php';Auth::requireLogin();
$hasAccess=ManagementReportsRepository::canAggregate()||ManagementReportsRepository::canReview();foreach(array_keys(ManagementReportsRepository::TYPES) as $reportType)$hasAccess=$hasAccess||ManagementReportsRepository::canPrepare($reportType);if(!$hasAccess){http_response_code(403);exit('دسترسی غیرمجاز است.');}
