    if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('اعتبار درخواست منقضی شده است.','danger');redirect('/admin/management-reports.php');}
    try{ManagementReportsRepository::review((int)($_POST['submission_id']??0),(string)($_POST['action']??''),trim((string)($_POST['note']??'')));flash(($_POST['action']??'')==='approve'?'گزارش با موفقیت تأیید شد.':(($_POST['action']??'')==='return'?'گزارش برای اصلاح برگشت داده شد.':'گزارش بایگانی شد.'));}
    catch(InvalidArgumentException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('Management report review: '.$e->getMessage());flash('عملیات بررسی گزارش انجام نشد.','danger');}
