$filters=['period_key'=>trim((string)($_GET['period_key']??'')),'report_type'=>trim((string)($_GET['report_type']??'')),'submitter_id'=>(int)($_GET['submitter_id']??0),'status'=>trim((string)($_GET['status']??'')),'unit_id'=>(int)($_GET['unit_id']??0),'date_from'=>trim((string)($_GET['date_from']??'')),'date_to'=>trim((string)($_GET['date_to']??''))];
$rows=ManagementReportsRepository::list($filters);$allRows=ManagementReportsRepository::list();$stats=ManagementReportsRepository::stats($allRows);
if(($_GET['action']??'')==='excel'){
    $details=[];$fieldCatalog=[];
    foreach($rows as $row){$detail=ManagementReportsRepository::submission((int)$row['id']);if(!$detail)continue;$details[(int)$row['id']]=$detail;foreach($detail['values'] as $value){$catalogKey=$row['report_type'].'|'.($detail['template_version_no']??1).'|'.$value['field_key'];$fieldCatalog[$catalogKey]=$value['label'].' — نسخه '.($detail['template_version_no']??1);}}
    $headers=['شناسه','نوع گزارش','نسخه قالب','دوره','ثبت‌کننده','واحد','وضعیت','تاریخ ثبت'];foreach($fieldCatalog as $label)$headers[]=$label;$sheet=[$headers];
    foreach($rows as $row){$detail=$details[(int)$row['id']]??null;if(!$detail)continue;$map=[];foreach($detail['values'] as $value){$catalogKey=$row['report_type'].'|'.($detail['template_version_no']??1).'|'.$value['field_key'];$map[$catalogKey]=$value;}$line=[$row['id'],ManagementReportsRepository::TYPES[$row['report_type']]??$row['report_type'],$detail['template_version_no']??1,$row['period_title'],$row['submitter_name'],$row['unit_title'],ManagementReportsRepository::STATUSES[$row['status']]??$row['status'],$row['created_at']];foreach(array_keys($fieldCatalog) as $catalogKey){$value=$map[$catalogKey]??null;$line[]=$value?($value['value_json']!==null?self_join_report_json($value['value_json']):($value['value_number']!==null?$value['value_number']:$value['value_text'])):'';}$sheet[]=$line;}
    CeoDashboardExcel::output(['گزارشات مدیران'=>$sheet],'management-reports-'.date('Y-m-d').'.xlsx');
