</form></details><?php endif?></div></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="6"><div class="mr-empty">گزارشی مطابق فیلترها پیدا نشد.</div></td></tr><?php endif?></tbody></table></div></section>
